CREATE OR REPLACE FUNCTION public.get_all_projects_data(p_since_timestamp timestamp with time zone DEFAULT '1970-01-01 00:00:00+00'::timestamp with time zone)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_result JSON;
  v_user_id UUID;
BEGIN
  v_user_id := auth.uid();

  SELECT json_build_object(
    'projects', COALESCE((
      SELECT json_agg(row_to_json(p.*) ORDER BY p.updated_at DESC)
      FROM (
        SELECT id, owner_id, title, description, created_date, updated_at, deleted_at, version
        FROM public.projects
        WHERE owner_id = v_user_id
          AND deleted_at IS NULL
          AND updated_at > p_since_timestamp
      ) p
    ), '[]'::json),
    'server_time', now()
  ) INTO v_result;

  RETURN v_result;
END;
$function$
